function useToast() {
  const [toast,setToast] = useState("");
  const show = (msg) => { setToast(msg); setTimeout(()=>setToast(""), 2200); };
  return {toast, show};
}

function Logo({dark=false}) {
  return <Link to="/" className="logo"><span className="logo-mark">M</span><span>Marketly</span></Link>
}

function ThemeButton({dark,setDark}) {
  return <button className="icon-btn" onClick={()=>setDark(!dark)} title="Toggle theme">{dark?<Sun size={18}/>:<Moon size={18}/>}</button>
}

function PublicNav({dark,setDark}) {
  return <header className="public-nav">
    <Logo/>
    <nav className="desktop-nav">
      <NavLink to="/">Home</NavLink><NavLink to="/stores">Explore Stores</NavLink>
      <a href="#features">Features</a><a href="#pricing">Pricing</a><a href="#about">About</a>
    </nav>
    <div className="nav-actions"><ThemeButton dark={dark} setDark={setDark}/><Link className="btn ghost" to="/login">Login</Link><Link className="btn primary" to="/register">Get Started <ArrowRight size={16}/></Link></div>
  </header>
}

