function Footer(){return <footer><div className="footer-main"><div><Logo/><p>Powering the next generation of independent businesses.</p></div><div><b>Product</b><a href="#features">Features</a><a href="#pricing">Pricing</a><Link to="/stores">Stores</Link></div><div><b>Company</b><a>About</a><a>Help Center</a><a>Contact</a></div><div><b>Legal</b><a>Privacy</a><a>Terms</a></div></div><div className="footer-bottom">© 2026 Marketly. All rights reserved.<span>Made for modern commerce.</span></div></footer>}

function Auth({mode="login"}) {
  const navigate=useNavigate(); const [role,setRole]=useState(mode==="vendor"?"vendor":"customer"); const [loading,setLoading]=useState(false); const [error,setError]=useState("");
  const submit=async e=>{e.preventDefault();setLoading(true);setError("");const fd=new FormData(e.currentTarget);try{const data={name:fd.get("name"),email:fd.get("email"),password:fd.get("password"),role,businessName:fd.get("businessName"),phone:fd.get("phone")};if(mode!=="login"&&data.password!==fd.get("confirmPassword"))throw new Error("Passwords do not match");const result=mode==="login"?await login({email:data.email,password:data.password}):await register(data);navigate(result.user.role==="vendor"?"/vendor/dashboard":"/customer/dashboard")}catch(err){setError(err.response?.data?.message||err.message||"Unable to continue")}finally{setLoading(false)}};
  const title=mode==="login"?"Welcome back":mode==="vendor"?"Start selling with Marketly":"Create your Marketly account";
  return <div className="auth-page"><div className="auth-visual"><Logo/><div><div className="eyebrow">ONE PLATFORM. EVERY STORE.</div><h1>Commerce that moves at the speed of your ambition.</h1><p>Run your store, serve your customers and understand your growth from one beautiful workspace.</p></div><div className="auth-quote">“Marketly made our operations feel ten times simpler.”<small>— Priya, Urban Threads</small></div></div>
    <div className="auth-form-wrap"><div className="mobile-auth-logo"><Logo/></div><div className="auth-form"><Link className="back-link" to="/"><ChevronLeft size={16}/> Back to home</Link><h2>{title}</h2><p className="muted">{mode==="login"?"Sign in to continue to your workspace.":"Set up your account in less than a minute."}</p>
      {mode!=="login"&&<div className="role-tabs"><button className={role==="customer"?"active":""} onClick={()=>setRole("customer")}>Customer</button><button className={role==="vendor"?"active":""} onClick={()=>setRole("vendor")}>Vendor</button></div>}
      <form onSubmit={submit}>
        {error&&<div className="error-note">{error}</div>}
        {mode!=="login"&&<><label>Full name<input name="name" required placeholder="Your full name"/></label>{role==="vendor"&&<label>Business name<input name="businessName" required placeholder="Your store name"/></label>}</>}
        <label>Email<input name="email" type="email" required placeholder="you@example.com"/></label>
        {mode==="vendor"&&<label>Phone<input name="phone" placeholder="+91 98765 43210"/></label>}
        <label>Password<input name="password" type="password" required placeholder="••••••••"/></label>
        {mode!=="login"&&<label>Confirm password<input name="confirmPassword" type="password" required placeholder="••••••••"/></label>}
        {mode==="login"&&<div className="form-row"><label className="check"><input type="checkbox"/> Remember me</label><Link to="/forgot-password">Forgot password?</Link></div>}
        <button className="btn primary full xl" disabled={loading}>{loading?"Signing in…":mode==="login"?"Login":role==="vendor"?"Create vendor account":"Create account"}</button>
      </form>
      <div className="divider"><span>or</span></div><button className="social-btn"><Globe2 size={17}/> Continue with Google</button>
      <p className="auth-switch">{mode==="login"?"Don't have an account? ":"Already have an account? "}<Link to={mode==="login"?"/register":"/login"}>{mode==="login"?"Create one":"Sign in"}</Link></p>
    </div></div></div>
}

function AppShell({role,children,dark,setDark}) {
  const [collapsed,setCollapsed]=useState(false); const navigate=useNavigate();
  const menus = role==="vendor" ? [
    ["Dashboard","/vendor/dashboard",LayoutDashboard],["My Store","/vendor/store",Store],["Products","/vendor/products",Package],["Categories","#",Tag],["Inventory","/vendor/inventory",Boxes],["Orders","/vendor/orders",ShoppingBag],["Customers","#",Users],["Discounts","#",Tag],["Analytics","/vendor/analytics",BarChart3],["Reviews","#",Star],["Store Settings","#",Settings]
  ] : role==="admin" ? [
    ["Overview","/admin/dashboard",LayoutDashboard],["Vendors","/admin/vendors",Users],["Stores","/admin/stores",Store],["Customers","/admin/customers",Users],["Products","/vendor/products",Package],["Orders","/vendor/orders",ShoppingBag],["Transactions","#",Wallet],["Analytics","/admin/analytics",BarChart3],["Categories","#",Tag],["Reports","#",Download],["System Settings","#",Settings]
  ] : [
    ["Dashboard","/customer/dashboard",LayoutDashboard],["Browse Stores","/stores",Store],["Products","/stores",Package],["Wishlist","#",Heart],["Cart","/cart",ShoppingCart],["Orders","/customer/orders",ShoppingBag],["Addresses","#",MapPin],["Profile","#",UserRound],["Notifications","#",Bell],["Settings","#",Settings]
  ];
  return <div className={"app-shell "+(collapsed?"collapsed":"")}><aside className="sidebar"><div className="side-brand"><Logo/><button className="icon-btn" onClick={()=>setCollapsed(!collapsed)}><ChevronLeft size={17}/></button></div><div className="role-pill">{role==="admin"?"SUPER ADMIN":role.toUpperCase()}</div><nav>{menus.map(([name,path,Icon])=><NavLink key={name} to={path} className={({isActive})=>isActive?"active":""}><Icon size={18}/><span>{name}</span></NavLink>)}</nav><div className="sidebar-bottom"><button onClick={()=>{logout();navigate("/")}}><LogOut size={18}/><span>Logout</span></button></div></aside>
    <div className="app-main"><header className="app-top"><button className="mobile-menu icon-btn" onClick={()=>setCollapsed(!collapsed)}><Menu/></button><div className="global-search"><Search size={18}/><input placeholder="Search anything…"/><kbd>⌘ K</kbd></div><div className="top-actions"><ThemeButton dark={dark} setDark={setDark}/><button className="icon-btn"><CircleHelp size={18}/></button><button className="icon-btn notification"><Bell size={18}/><i/></button><div className="profile-mini"><span>{role==="admin"?"SA":role==="vendor"?"AM":"RK"}</span><div><b>{role==="admin"?"Super Admin":role==="vendor"?"Aarav Mehta":"Riya Kapoor"}</b><small>{role==="admin"?"Platform Owner":role==="vendor"?"Urban Threads":"Customer"}</small></div><ChevronDown size={15}/></div></div></header><main className="app-content">{children}</main></div></div>
}

function StatCard({label,value,change,Icon,negative=false}){return <div className="stat-card"><div className="stat-top"><span className="stat-icon"><Icon size={18}/></span><span className={negative?"change negative":"change"}>{change}</span></div><small>{label}</small><strong>{value}</strong></div>}

function Dashboard({role}) {
  const admin=role==="admin"; const customer=role==="customer";
  if(customer) return <CustomerDashboard/>;
  return <AppShellInner title={admin?"Platform overview":"Good morning, Aarav 👋"} subtitle={admin?"Monitor your entire commerce ecosystem from one place.":"Here’s what’s happening with Urban Threads today."} role={role}>
    <div className="stats-grid">{(admin?[
      ["Total Vendors","1,284","+8.2%",Users],["Active Stores","1,146","+6.4%",Store],["Total Customers","82.4K","+14.2%",Users],["Platform Revenue","₹18.6L","+21.8%",Wallet],["Total Orders","42,891","+12.6%",ShoppingBag],["Total Products","24,862","+9.1%",Package],["Pending Approvals","38","Needs review",Clock3],["Failed Transactions","17","-4.3%",AlertTriangle]
    ]:[
      ["Total Revenue","₹9,32,480","+18.4%",Wallet],["Today's Revenue","₹38,420","+12.8%",TrendingUp],["Total Orders","1,284","+14.6%",ShoppingBag],["Pending Orders","28","Needs action",Clock3],["Total Products","128","+8.2%",Package],["Low Stock","5","Needs attention",AlertTriangle],["Customers","8,492","+9.2%",Users],["Conversion Rate","4.82%","+0.6%",BarChart3]
    ]).map(x=><StatCard key={x[0]} label={x[0]} value={x[1]} change={x[2]} Icon={x[3]} negative={x[0]==="Failed Transactions"}/>)}</div>
    <div className="dashboard-grid"><ChartCard title={admin?"Platform revenue":"Revenue overview"} meta="Last 6 months"><ResponsiveContainer width="100%" height={300}><AreaChart data={revenueData}><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopOpacity=".3"/><stop offset="100%" stopOpacity=".02"/></linearGradient></defs><CartesianGrid strokeDasharray="4 4" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area type="monotone" dataKey="revenue" stroke="#635bff" fill="url(#area)" strokeWidth={3}/></AreaChart></ResponsiveContainer></ChartCard>
      <ChartCard title="Sales by category" meta="This month"><ResponsiveContainer width="100%" height={300}><PieChart><Pie data={categoryData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={72} outerRadius={105} paddingAngle={4}>{categoryData.map((_,i)=><Cell key={i} fill={["#635bff","#35a7ff","#ff6b9d","#21b573","#f5a524"][i]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div className="legend">{categoryData.map((x,i)=><span key={x.name}><i style={{background:["#635bff","#35a7ff","#ff6b9d","#21b573","#f5a524"][i]}}/>{x.name}<b>{x.value}%</b></span>)}</div></ChartCard>
    </div>
    <div className="content-grid"><div className="panel"><PanelHead title="Recent orders" action="View all" link={admin?"/vendor/orders":"/vendor/orders"}/><OrderTable rows={orders}/></div><div className="panel"><PanelHead title="Top products"/><div className="top-products">{products.slice(0,5).map(p=><div className="top-product" key={p.id}><img src={p.image}/><div><b>{p.name}</b><small>{p.store} · {p.sales} sold</small></div><strong>{money(p.price)}</strong></div>)}</div></div></div>
  </AppShellInner>
}

function CustomerDashboard(){return <AppShellInner role="customer" title="Welcome back, Riya 👋" subtitle="Here’s your shopping overview."><div className="customer-hero"><div><div className="eyebrow">YOUR SHOPPING SPACE</div><h2>Find something you'll love.</h2><p>Explore independent stores and discover products picked for you.</p><Link className="btn white" to="/stores">Explore stores <ArrowRight size={16}/></Link></div><ShoppingBag size={130}/></div><div className="stats-grid three"><StatCard label="Active orders" value="3" change="2 arriving soon" Icon={Truck}/><StatCard label="Wishlist items" value="12" change="+3 this week" Icon={Heart}/><StatCard label="Cart total" value="₹8,497" change="4 items" Icon={ShoppingCart}/></div><div className="content-grid"><div className="panel"><PanelHead title="Recent orders" action="View all" link="/customer/orders"/><OrderTable rows={orders.slice(0,4)}/></div><div className="panel"><PanelHead title="Recommended for you"/><div className="product-list">{products.slice(0,4).map(p=><ProductRow key={p.id} p={p}/>)}</div></div></div></AppShellInner>}

function AppShellInner({role,title,subtitle,children}) {
  const dark=window.__marketlyDark||false; return <AppShell role={role} dark={dark} setDark={v=>{window.__marketlyDark=v;document.documentElement.classList.toggle("dark",v);window.dispatchEvent(new Event("theme"))}}><div className="page-head"><div><h1>{title}</h1><p>{subtitle}</p></div><div className="head-actions">{role==="vendor"&&<Link className="btn primary" to="/vendor/products/new"><Plus size={17}/> Add product</Link>}{role==="admin"&&<button className="btn secondary"><Download size={17}/> Export report</button>}</div></div>{children}</AppShell>}

function ChartCard({title,meta,children}){return <div className="panel chart-panel"><PanelHead title={title} meta={meta}/>{children}</div>}
function PanelHead({title,action,link,meta}){return <div className="panel-head"><div><h3>{title}</h3>{meta&&<small>{meta}</small>}</div>{action&&<Link to={link||"#"} className="text-link">{action} <ArrowRight size={14}/></Link>}</div>}
function OrderTable({rows}){return <div className="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Store</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><b>{o.id}</b><small>{o.date}</small></td><td>{o.customer}</td><td>{o.store}</td><td><b>{money(o.amount)}</b><small>{o.payment}</small></td><td><Status text={o.status}/></td><td><button className="icon-btn"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div>}
function Status({text}){return <span className={"status "+text.toLowerCase().replaceAll(" ","-")}><i/>{text}</span>}

function Stores(){const [q,setQ]=useState("");const [cat,setCat]=useState("All");const filtered=stores.filter(s=>(cat==="All"||s.category===cat)&&s.name.toLowerCase().includes(q.toLowerCase()));return <div><PublicNav dark={false} setDark={()=>{}}/><main className="marketplace"><div className="market-head"><div><div className="eyebrow">MARKETPLACE</div><h1>Discover independent stores.</h1><p>Shop unique products from businesses building something special.</p></div><div className="market-search"><Search size={18}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search stores…"/></div></div><div className="filter-row">{["All","Fashion","Electronics","Beauty","Home & Living","Fitness"].map(c=><button className={cat===c?"active":""} onClick={()=>setCat(c)} key={c}>{c}</button>)}<button className="filter-button"><Filter size={16}/> Filters</button></div><div className="store-grid">{filtered.map(s=><Link to={"/store/"+s.slug} className="store-card" key={s.id}><div className="store-cover" style={{background:s.color}}><div className="store-logo">{s.icon}</div><span className="verified"><Check size={12}/> Verified</span></div><div className="store-body"><div className="store-title"><div><h3>{s.name}</h3><small>{s.category}</small></div><span><Star size={14} fill="currentColor"/> {s.rating}</span></div><div className="store-meta"><span><Package size={14}/> {s.products} products</span><span><MapPin size={14}/> {s.location}</span></div><span className="store-visit">Visit store <ArrowRight size={15}/></span></div></Link>)}</div></main><Footer/></div>}

function StoreFront(){const {storeSlug}=useParams();const s=stores.find(x=>x.slug===storeSlug)||stores[0];const items=products.filter(p=>p.store===s.name);return <div><PublicNav dark={false} setDark={()=>{}}/><main className="storefront"><div className="store-banner" style={{background:s.color}}><div className="store-logo big">{s.icon}</div><div><div className="eyebrow">VERIFIED STORE</div><h1>{s.name}</h1><p>Thoughtfully selected {s.category.toLowerCase()} products for modern living.</p><div className="rating"><Star size={16} fill="currentColor"/> {s.rating} · {s.products} products · {s.location}</div></div><button className="btn secondary"><Heart size={16}/> Follow store</button></div><div className="store-tabs"><span className="active">All products</span><span>New arrivals</span><span>Best sellers</span><span>About</span></div><div className="section-inline"><div><h2>All products</h2><p>{items.length || 4} products from {s.name}</p></div><button className="btn secondary"><SlidersHorizontal size={16}/> Sort</button></div><div className="product-grid">{(items.length?items:products.slice(0,4)).map(p=><ProductCard p={p} key={p.id}/>)}</div></main></div>}

function ProductCard({p}){const [liked,setLiked]=useState(false);return <div className="product-card"><div className="product-image"><img src={p.image}/><button onClick={()=>setLiked(!liked)} className={"heart "+(liked?"liked":"")}><Heart size={17} fill={liked?"currentColor":"none"}/></button>{p.compare>p.price&&<span className="sale">-{Math.round((1-p.price/p.compare)*100)}%</span>}</div><div className="product-info"><small>{p.store}</small><h3>{p.name}</h3><div className="rating"><Star size={13} fill="currentColor"/> {p.rating}</div><div className="product-price"><b>{money(p.price)}</b><del>{money(p.compare)}</del></div><button className="btn primary full" onClick={()=>{const c=JSON.parse(localStorage.getItem("marketly_cart")||"[]");const i=c.findIndex(x=>x.id===p.id);if(i>=0)c[i].quantity+=1;else c.push({...p,quantity:1});localStorage.setItem("marketly_cart",JSON.stringify(c));window.dispatchEvent(new Event("marketly-cart"));}}>Add to cart</button></div></div>}

function ProductDetail(){const {productId}=useParams();const p=products.find(x=>x.id===productId)||products[0];return <div><PublicNav dark={false} setDark={()=>{}}/><main className="detail-page"><div className="breadcrumbs">Stores <ChevronRight size={14}/> {p.store} <ChevronRight size={14}/> {p.name}</div><div className="detail-grid"><div className="gallery"><img src={p.image}/><div><img src={p.image}/><img src={p.image}/><img src={p.image}/></div></div><div className="detail-copy"><small className="eyebrow">{p.category.toUpperCase()}</small><h1>{p.name}</h1><div className="detail-rating"><span><Star size={16} fill="currentColor"/> {p.rating}</span><span>128 reviews</span><span>In stock</span></div><div className="detail-price">{money(p.price)} <del>{money(p.compare)}</del><span>Save {Math.round((1-p.price/p.compare)*100)}%</span></div><p>Premium quality product designed for everyday use. Built with thoughtful materials, modern details and the reliability you expect from a Marketly store.</p><div className="option"><b>Color</b><div><button className="swatch selected"></button><button className="swatch"></button><button className="swatch"></button></div></div><div className="option"><b>Quantity</b><div className="qty"><button>−</button><span>1</span><button>+</button></div></div><div className="detail-actions"><button className="btn primary xl" onClick={()=>{const c=JSON.parse(localStorage.getItem("marketly_cart")||"[]");const i=c.findIndex(x=>x.id===p.id);if(i>=0)c[i].quantity+=1;else c.push({...p,quantity:1});localStorage.setItem("marketly_cart",JSON.stringify(c));window.dispatchEvent(new Event("marketly-cart"));}}>Add to cart</button><button className="btn secondary xl"><Heart size={18}/> Wishlist</button></div><div className="secure"><ShieldCheck size={19}/><span><b>Secure checkout</b><small>30-day returns · Buyer protection</small></span></div></div></div><div className="reviews panel"><PanelHead title="Customer reviews" meta="4.8 average from 128 reviews"/><div className="review-grid"><div className="review-score"><strong>4.8</strong><div className="stars">★★★★★</div><small>128 reviews</small></div>{["Excellent quality and quick delivery.","Looks even better in person. Very happy.","Great product for the price."].map((x,i)=><div className="review" key={x}><div>★★★★★</div><p>{x}</p><small>{["Neha S.","Rahul K.","Sana M."][i]} · Verified buyer</small></div>)}</div></div></main></div>}

function Cart(){return <AppShellInner role="customer" title="Your cart" subtitle="Review items from your favorite Marketly stores."><div className="cart-layout"><div className="cart-items"><div className="cart-vendor"><h3><Store size={17}/> Urban Threads <span>2 items</span></h3>{products.slice(0,2).map(p=><div className="cart-item" key={p.id}><img src={p.image}/><div><h3>{p.name}</h3><small>{p.store}</small><button>Remove</button></div><div className="qty"><button>−</button><span>1</span><button>+</button></div><strong>{money(p.price)}</strong></div>)}</div><div className="cart-vendor"><h3><Store size={17}/> TechNova <span>2 items</span></h3>{products.slice(2,4).map(p=><div className="cart-item" key={p.id}><img src={p.image}/><div><h3>{p.name}</h3><small>{p.store}</small><button>Remove</button></div><div className="qty"><button>−</button><span>1</span><button>+</button></div><strong>{money(p.price)}</strong></div>)}</div></div><div className="summary panel"><h3>Order summary</h3><div><span>Subtotal</span><b>₹11,797</b></div><div><span>Delivery</span><b>₹199</b></div><div><span>Tax</span><b>₹1,179</b></div><div className="promo"><input placeholder="Promo code"/><button>Apply</button></div><div className="total"><span>Total</span><strong>₹13,175</strong></div><Link className="btn primary full xl" to="/checkout">Proceed to checkout <ArrowRight size={17}/></Link><Link className="continue" to="/stores"><ChevronLeft size={15}/> Continue shopping</Link></div></div></AppShellInner>}

function Checkout(){const [step,setStep]=useState(1);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const placeOrder=async()=>{setBusy(true);setError("");try{const cart=JSON.parse(localStorage.getItem("marketly_cart")||"[]");const created=await api.post("/orders",{items:cart.map(x=>({product:x.id,quantity:x.quantity||1})),shippingAddress:{firstName:"Riya",lastName:"Kapoor",city:"Pune",pin:"411001",state:"Maharashtra",phone:"+91 98765 43210"},paymentMethod:"stripe"});const session=await api.post("/payments/checkout-session",{orderId:created.data._id});if(session.data.url)window.location.href=session.data.url;else throw new Error("Stripe checkout could not be created")}catch(err){setError(err.response?.data?.message||err.message||"Checkout failed");setBusy(false)}};return <AppShellInner role="customer" title="Checkout" subtitle="Secure checkout powered by Marketly."><div className="checkout-steps">{["Shipping","Delivery","Payment","Review"].map((s,i)=><div className={step===i+1?"active":step>i+1?"done":""} key={s}><span>{step>i+1?<Check size={14}/>:i+1}</span>{s}</div>)}</div><div className="checkout-layout"><div className="checkout-card panel">{step===1&&<><h2>Shipping address</h2><div className="form-grid"><label>First name<input defaultValue="Riya"/></label><label>Last name<input defaultValue="Kapoor"/></label><label className="span2">Address<input placeholder="House / flat / street"/></label><label>City<input defaultValue="Pune"/></label><label>PIN code<input defaultValue="411001"/></label><label>State<select><option>Maharashtra</option></select></label><label>Phone<input defaultValue="+91 98765 43210"/></label></div></>}{step===2&&<><h2>Delivery method</h2>{["Standard delivery · 3–5 business days · ₹99","Express delivery · 1–2 business days · ₹249"].map((x,i)=><label className="delivery-option" key={x}><input type="radio" defaultChecked={i===0} name="delivery"/><span><b>{x.split(" · ")[0]}</b><small>{x.split(" · ").slice(1).join(" · ")}</small></span></label>)}</>}{step===3&&<><h2>Payment</h2><div className="payment-tabs"><button className="active"><CreditCard size={18}/> Card</button><button>UPI</button><button>Cash on delivery</button></div><div className="form-grid"><label className="span2">Card number<input placeholder="1234 5678 9012 3456"/></label><label>Name on card<input placeholder="Riya Kapoor"/></label><label>Expiry<input placeholder="MM / YY"/></label><label>CVV<input placeholder="•••"/></label></div><div className="secure"><ShieldCheck size={19}/><span><b>Your payment is secure</b><small>Stripe-ready payment architecture.</small></span></div></>}{step===4&&<><h2>Review your order</h2><div className="review-order">{products.slice(0,3).map(p=><div key={p.id}><img src={p.image}/><span><b>{p.name}</b><small>Qty 1 · {p.store}</small></span><strong>{money(p.price)}</strong></div>)}</div><div className="success-note"><CheckCircle2/><span><b>Ready to place order</b><small>Estimated delivery: 16–18 Sep 2026</small></span></div></>}{error&&<div className="error-note">{error}</div>}<div className="checkout-actions">{step>1&&<button className="btn secondary" onClick={()=>setStep(step-1)}>Back</button>}<button className="btn primary" onClick={()=>step<4?setStep(step+1):placeOrder()} disabled={busy}>{busy?"Creating secure checkout…":step===4?"Pay securely with Stripe":"Continue"} <ArrowRight size={17}/></button></div></div><div className="summary panel"><h3>Order summary</h3>{products.slice(0,3).map(p=><div className="summary-item" key={p.id}><span>{p.name}<small>Qty 1</small></span><b>{money(p.price)}</b></div>)}<hr/><div><span>Subtotal</span><b>₹10,997</b></div><div><span>Shipping</span><b>₹99</b></div><div><span>Tax</span><b>₹1,099</b></div><div className="total"><span>Total</span><strong>₹12,195</strong></div></div></div></AppShellInner>}

function Success(){return <AppShellInner role="customer" title=""><div className="success-page"><div className="success-icon"><Check size={34}/></div><div className="eyebrow">ORDER CONFIRMED</div><h1>Thanks, Riya!</h1><p>Your order has been placed successfully. We’ve sent confirmation details to your email.</p><div className="order-success-card panel"><div><small>ORDER ID</small><b>#MK-10483</b></div><div><small>PAYMENT</small><b>Paid · Card</b></div><div><small>ESTIMATED DELIVERY</small><b>16–18 Sep 2026</b></div><div><small>TOTAL</small><b>₹12,195</b></div></div><div className="success-products">{products.slice(0,3).map(p=><div key={p.id}><img src={p.image}/><span><b>{p.name}</b><small>{p.store}</small></span></div>)}</div><div className="success-actions"><Link className="btn primary" to="/customer/orders">Track order <Truck size={17}/></Link><Link className="btn secondary" to="/stores">Continue shopping</Link></div></div></AppShellInner>}

function OrdersPage({admin=false}){return <AppShellInner role={admin?"admin":"customer"} title={admin?"All platform orders":"Your orders"} subtitle={admin?"Manage orders across the Marketly ecosystem.":"Track purchases from every store in one place."}><div className="toolbar"><div className="toolbar-search"><Search size={17}/><input placeholder="Search orders…"/></div><button className="btn secondary"><Filter size={16}/> Filters</button><button className="btn secondary">Last 30 days <ChevronDown size={15}/></button></div><div className="panel"><OrderTable rows={orders.concat(orders.slice(0,2))}/><div className="pagination"><span>Showing 1–6 of 128 orders</span><div><button><ChevronLeft size={15}/></button><button className="active">1</button><button>2</button><button>3</button><button><ChevronRight size={15}/></button></div></div></div></AppShellInner>}

function ProductsPage(){return <AppShellInner role="vendor" title="Products" subtitle="Manage your catalog, pricing and availability."><div className="toolbar"><div className="toolbar-search"><Search size={17}/><input placeholder="Search products…"/></div><button className="btn secondary"><Filter size={16}/> Filter</button><Link className="btn primary" to="/vendor/products/new"><Plus size={17}/> Add product</Link></div><div className="panel"><div className="bulk-bar"><span>128 products</span><span className="muted">Select products to bulk edit</span></div><div className="table-wrap"><table><thead><tr><th><input type="checkbox"/></th><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Sales</th><th></th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td><input type="checkbox"/></td><td><div className="table-product"><img src={p.image}/><span><b>{p.name}</b><small>SKU-{p.id.toUpperCase()}</small></span></div></td><td>{p.category}</td><td><b>{money(p.price)}</b><small>Cost ₹{Math.round(p.price*.6)}</small></td><td><b>{p.stock}</b><small>{p.stock<10?"Low stock":"In stock"}</small></td><td><Status text={p.stock<10?"Low stock":"Active"}/></td><td>{p.sales}</td><td><button className="icon-btn"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div><div className="pagination"><span>Showing 8 of 128 products</span><div><button className="active">1</button><button>2</button><button>3</button><button>…</button><button>16</button></div></div></div></AppShellInner>}

function ProductForm(){const [saved,setSaved]=useState(false);return <AppShellInner role="vendor" title="Add product" subtitle="Create a product customers will love."><div className="form-page-grid"><div><div className="panel form-panel"><h3>Basic information</h3><label>Product name<input placeholder="e.g. Premium Sneakers"/></label><label>Description<textarea rows="5" placeholder="Describe your product…"/></label><div className="form-grid"><label>Category<select><option>Fashion</option><option>Electronics</option><option>Beauty</option></select></label><label>Brand<input placeholder="Brand name"/></label></div></div><div className="panel form-panel"><h3>Pricing</h3><div className="form-grid"><label>Price<input placeholder="₹ 0.00"/></label><label>Compare-at price<input placeholder="₹ 0.00"/></label><label>Cost price<input placeholder="₹ 0.00"/></label><label>Tax<input placeholder="18%"/></label></div></div><div className="panel form-panel"><h3>Inventory</h3><div className="form-grid"><label>SKU<input placeholder="SKU-001"/></label><label>Stock quantity<input placeholder="0"/></label><label>Low-stock threshold<input defaultValue="10"/></label></div><label className="check"><input type="checkbox" defaultChecked/> Track inventory</label><label className="check"><input type="checkbox"/> Allow backorders</label></div><div className="panel form-panel"><h3>Variants</h3><div className="variant-row"><input placeholder="Option name e.g. Size"/><input placeholder="Values e.g. S, M, L"/><button className="icon-btn"><Trash2 size={16}/></button></div><button className="btn secondary"><Plus size={16}/> Add variant</button></div></div><div><div className="panel form-panel"><h3>Product images</h3><div className="upload-box"><Package size={27}/><b>Drop images here</b><small>or click to browse · PNG, JPG up to 5MB</small><button className="btn secondary">Upload images</button></div></div><div className="panel form-panel"><h3>Search engine listing</h3><label>Meta title<input placeholder="Product title"/></label><label>Meta description<textarea rows="3" placeholder="SEO description"/></label><label>URL slug<input placeholder="premium-sneakers"/></label></div><div className="panel form-panel"><h3>Status</h3><select><option>Active</option><option>Draft</option><option>Archived</option></select></div><button className="btn primary full xl" onClick={()=>setSaved(true)}>{saved?"Product saved ✓":"Save product"}</button></div></div></AppShellInner>}

function Inventory(){return <AppShellInner role="vendor" title="Inventory" subtitle="Monitor stock levels and inventory activity."><div className="stats-grid three"><StatCard label="Total units" value="3,842" change="+218 this month" Icon={Boxes}/><StatCard label="Low stock" value="5" change="Needs attention" Icon={AlertTriangle}/><StatCard label="Out of stock" value="2" change="Urgent" Icon={Package}/></div><div className="panel"><PanelHead title="Inventory levels" action="Bulk update"/><div className="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Current stock</th><th>Reserved</th><th>Available</th><th>Threshold</th><th>Status</th><th></th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td><div className="table-product"><img src={p.image}/><b>{p.name}</b></div></td><td>SKU-{p.id.toUpperCase()}</td><td>{p.stock}</td><td>{Math.floor(p.stock*.1)}</td><td><b>{Math.floor(p.stock*.9)}</b></td><td>10</td><td><Status text={p.stock===0?"Out of stock":p.stock<10?"Low stock":"In stock"}/></td><td><button className="btn tiny secondary">Update</button></td></tr>)}</tbody></table></div></div></AppShellInner>}

function Analytics({admin=false}){return <AppShellInner role={admin?"admin":"vendor"} title={admin?"Platform analytics":"Analytics"} subtitle="Turn commerce data into your next decision."><div className="analytics-filters"><div className="segmented"><button>Today</button><button>7 days</button><button className="active">30 days</button><button>3 months</button><button>1 year</button></div><button className="btn secondary"><Download size={16}/> Export report</button></div><div className="stats-grid four"><StatCard label={admin?"Total GMV":"Revenue"} value="₹18.6L" change="+21.8%" Icon={Wallet}/><StatCard label={admin?"Platform commission":"Gross sales"} value="₹2.42L" change="+18.2%" Icon={TrendingUp}/><StatCard label="Average order value" value="₹4,286" change="+6.8%" Icon={CreditCard}/><StatCard label="Conversion rate" value="4.82%" change="+0.6%" Icon={BarChart3}/></div><div className="dashboard-grid"><ChartCard title="Revenue trend" meta="Last 30 days"><ResponsiveContainer width="100%" height={310}><AreaChart data={revenueData}><CartesianGrid strokeDasharray="4 4" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area type="monotone" dataKey="revenue" stroke="#635bff" fillOpacity=".12" fill="#635bff" strokeWidth={3}/></AreaChart></ResponsiveContainer></ChartCard><ChartCard title="Orders trend" meta="Last 30 days"><ResponsiveContainer width="100%" height={310}><BarChart data={revenueData}><CartesianGrid strokeDasharray="4 4" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="orders" fill="#35a7ff" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></ChartCard></div><div className="content-grid"><div className="panel"><PanelHead title="Top products"/>{products.slice(0,6).map((p,i)=><div className="analytics-row" key={p.id}><span className="rank">{i+1}</span><img src={p.image}/><div><b>{p.name}</b><small>{p.category}</small></div><strong>{money(p.price*p.sales)}</strong><span className="positive">+{12+i*3}%</span></div>)}</div><div className="panel"><PanelHead title="Customer growth"/><div className="big-number">8,492 <span>customers</span></div><ResponsiveContainer width="100%" height={210}><AreaChart data={revenueData}><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis hide/><Area type="monotone" dataKey="orders" stroke="#21b573" fill="#21b573" fillOpacity=".1" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></div></AppShellInner>}

function VendorStore(){return <AppShellInner role="vendor" title="My Store" subtitle="Configure your storefront and brand experience."><div className="settings-grid"><div className="panel form-panel"><h3>Store profile</h3><div className="store-avatar-row"><div className="store-logo">UT</div><button className="btn secondary">Change logo</button></div><label>Store name<input defaultValue="Urban Threads"/></label><label>Store slug<input defaultValue="urban-threads"/></label><label>Description<textarea rows="4" defaultValue="Modern essentials for everyday style."/></label><div className="form-grid"><label>Business category<select><option>Fashion</option></select></label><label>Email<input defaultValue="hello@urbanthreads.in"/></label><label>Phone<input defaultValue="+91 98765 43210"/></label><label>Location<input defaultValue="Mumbai, India"/></label></div><button className="btn primary">Save changes</button></div><div><div className="panel form-panel"><h3>Store appearance</h3><label>Theme<select><option>Marketly Minimal</option><option>Editorial</option><option>Bold</option></select></label><label>Primary color<input type="color" defaultValue="#635bff"/></label><label>Store banner<div className="banner-upload">Upload cover image</div></label><label className="check"><input type="checkbox" defaultChecked/> Show featured products</label></div><div className="panel preview-card"><div className="preview-head"><b>Store preview</b><button className="icon-btn"><ExternalLink size={16}/></button></div><div className="fake-store"><div className="fake-store-banner"></div><div className="fake-store-logo">UT</div><h3>Urban Threads</h3><small>Modern essentials for everyday style.</small><div className="fake-products">{products.slice(0,3).map(p=><img src={p.image} key={p.id}/>)}</div></div></div></div></div></AppShellInner>}

function AdminList({type}){const isVendor=type==="vendors";const rows=isVendor?[
  ["Aarav Mehta","Urban Threads","aarav@urbanthreads.in","128","₹9.32L","Active"],["Neha Kapoor","TechNova","neha@technova.in","86","₹7.84L","Active"],["Vikram Singh","Glow Beauty","vikram@glowbeauty.in","74","₹5.61L","Pending"],["Maya Joshi","HomeCraft","maya@homecraft.in","102","₹4.98L","Suspended"],["Arjun Rao","FitZone","arjun@fitzone.in","61","₹3.82L","Active"]
]:[
  ["Urban Threads","Aarav Mehta","Fashion","128","1,284","₹9.32L","Active"],["TechNova","Neha Kapoor","Electronics","86","984","₹7.84L","Active"],["Glow Beauty","Vikram Singh","Beauty","74","756","₹5.61L","Pending"],["HomeCraft","Maya Joshi","Home & Living","102","642","₹4.98L","Suspended"],["FitZone","Arjun Rao","Fitness","61","521","₹3.82L","Active"]
];return <AppShellInner role="admin" title={isVendor?"Vendor management":"Store management"} subtitle={isVendor?"Approve, monitor and manage every vendor on the platform.":"Manage all tenant storefronts and their status."}><div className="toolbar"><div className="toolbar-search"><Search size={17}/><input placeholder={"Search "+type+"…"}/></div><button className="btn secondary"><Filter size={16}/> Filters</button><button className="btn secondary">Export <Download size={15}/></button></div><div className="panel"><div className="table-wrap"><table><thead><tr>{(isVendor?["Vendor","Business","Email","Products","Revenue","Status","Joined",""]:["Store","Vendor","Category","Products","Orders","Revenue","Status","Created",""]).map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((x,j)=><td key={j}>{j===r.length-1?null:j===r.length-2?<Status text={x}/>:j===0?<b>{x}</b>:x}</td>)}<td><button className="icon-btn"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div><div className="pagination"><span>Showing 1–5 of {isVendor?"1,284 vendors":"1,146 stores"}</span><div><button className="active">1</button><button>2</button><button>3</button><button>…</button><button>52</button></div></div></div></AppShellInner>}

function AdminCustomers(){return <AppShellInner role="admin" title="Customers" subtitle="Manage customers across the Marketly platform."><div className="panel"><div className="table-wrap"><table><thead><tr><th>Customer</th><th>Email</th><th>Orders</th><th>Total spent</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody>{["Riya Kapoor","Aarav Shah","Kabir Joshi","Ananya Rao","Vihaan Patil"].map((n,i)=><tr key={n}><td><div className="profile-cell"><span>{n.split(" ").map(x=>x[0]).join("")}</span><b>{n}</b></div></td><td>{n.toLowerCase().replace(" ",".")}@example.com</td><td>{24-i*3}</td><td><b>{money(28400-i*2300)}</b></td><td><Status text="Active"/></td><td>Aug {10+i}, 2026</td><td><button className="icon-btn"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div></div></AppShellInner>}

function App(){const [dark,setDark]=useState(false);window.__marketlyDark=dark;return <BrowserRouter><Routes><Route path="/" element={<Landing dark={dark} setDark={setDark}/>}/><Route path="/login" element={<Auth mode="login"/>}/><Route path="/register" element={<Auth mode="register"/>}/><Route path="/vendor/register" element={<Auth mode="vendor"/>}/><Route path="/customer/register" element={<Auth mode="register"/>}/><Route path="/forgot-password" element={<Auth mode="login"/>}/><Route path="/stores" element={<Stores/>}/><Route path="/store/:storeSlug" element={<StoreFront/>}/><Route path="/product/:productId" element={<ProductDetail/>}/><Route path="/cart" element={<Cart/>}/><Route path="/checkout" element={<Checkout/>}/><Route path="/order-success/:orderId" element={<Success/>}/><Route path="/customer/dashboard" element={<Dashboard role="customer"/>}/><Route path="/customer/orders" element={<OrdersPage/>}/><Route path="/vendor/dashboard" element={<Dashboard role="vendor"/>}/><Route path="/vendor/store" element={<VendorStore/>}/><Route path="/vendor/products" element={<ProductsPage/>}/><Route path="/vendor/products/new" element={<ProductForm/>}/><Route path="/vendor/inventory" element={<Inventory/>}/><Route path="/vendor/orders" element={<OrdersPage admin={false}/>}/><Route path="/vendor/analytics" element={<Analytics/>}/><Route path="/admin/dashboard" element={<Dashboard role="admin"/>}/><Route path="/admin/vendors" element={<AdminList type="vendors"/>}/><Route path="/admin/stores" element={<AdminList type="stores"/>}/><Route path="/admin/customers" element={<AdminCustomers/>}/><Route path="/admin/analytics" element={<Analytics admin/>}/><Route path="*" element={<Landing dark={dark} setDark={setDark}/>}/></Routes></BrowserRouter>}

createRoot(document.getElementById("root")).render(<App/>);
